import React from "react";

const JobTable = ({ jobs, onDelete }) => {
  if (jobs.length === 0) {
    return <p style={{ padding: "20px", textAlign: "center" }}>No job openings yet.</p>;
  }

  return (
    <table>
      <thead>
        <tr>
          <th>Position</th>
          <th>Location</th>
          <th>Type</th>
          <th>Status</th>
          <th>Actions</th>
        </tr>
      </thead>
      <tbody>
        {jobs.map((job, index) => (
          <tr key={index}>
            <td>{job.title}</td>
            <td>{job.location}</td>
            <td>{job.type}</td>
            <td>{job.status}</td>
            <td>
              <div className="action-buttons">
                <button className="btn-delete" onClick={() => onDelete(index)}>
                  Delete
                </button>
              </div>
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
};

export default JobTable;
